WITH filtered AS (SELECT *, SUBSTRING(supplier_name, 1, 2) supplier_name_prefix, COALESCE(city, 'N/A') resolved_city FROM suppliers WHERE city IS NOT NULL), not_flagged AS (SELECT s.* FROM filtered s WHERE EXISTS (SELECT 1 FROM products c WHERE c.supplier_id = s.id AND c.supplier_id IS NOT NULL)), not_flagged_suppliers AS (SELECT s.* FROM not_flagged s WHERE EXISTS (SELECT 1 FROM products ch WHERE ch.supplier_id = s.id AND ch.stock_qty >= 253)), with_last AS (SELECT s.*, x.cost FROM not_flagged_suppliers s LEFT JOIN LATERAL (SELECT c.cost FROM products c WHERE c.supplier_id = s.id ORDER BY c.cost DESC, c.id DESC LIMIT 1) x ON TRUE), deduped AS (SELECT id, supplier_name, country, city, rating, supplier_name_prefix, resolved_city, cost FROM with_last QUALIFY ROW_NUMBER() OVER (PARTITION BY country ORDER BY rating DESC, id) = 1), filtered_suppliers AS (SELECT *, CASE WHEN city = 'New York' THEN 1 ELSE 0 END is_new_york, LENGTH(supplier_name) supplier_name_length, COALESCE(city, 'OTHER') city_filled FROM deduped WHERE city IS NOT NULL AND city IS NOT DISTINCT FROM 'Chiang Mai') SELECT id, supplier_name, country, supplier_name_prefix, resolved_city, is_new_york, supplier_name_length, city_filled, CASE WHEN country RLIKE '^(JP|TH)$' THEN 'EXTENDED' WHEN country RLIKE '^(US|SG)$' THEN 'GROUP_B' ELSE 'OTHER_ZONE' END AS country_zone FROM filtered_suppliers ORDER BY is_new_york DESC;
